}
}

function check() {
   var newValues= workflowData.getMetaDataMap().get("newValuesOfFields").toString();
   var oldValues= workflowData.getMetaDataMap().get("oldValuesOfFields").toString();
log.info("old:"+oldValues);
log.info("new:"+newValues);
var empActionFlag= workflowData.getMetaDataMap().get("empActionFlag");
log.info("empAction :"+empActionFlag);
if(empActionFlag== "disagree"){
if(newValues== oldValues){
log.info("result:true");
return true;
}else{
log.info("false");
return false;
}
}
else{
log.info("false");
return false;
}
}

