or_1820577570.script1:
function check() {
var userId= workflowData.getMetaDataMap().get("reviewerUserId").toString();
var ratingObt= workflowData.getMetaDataMap().get("ratingGiven").toString();
log.info("userId:"+userId);
log.info("ratingObt:"+ratingObt);
if((userId == "daniellegarcia") || (userId != "daniellegarcia" & ratingObt == "Consistently Exceeds Expectations") || (userId != "daniellegarcia" & ratingObt == "Needs Improvement")){
return true;
}else{
workflowData.getMetaDataMap().put("actionTakenByReviewer","");
return false;
}
}

