or.script1:
function check() {
   var action = workflowData.getMetaDataMap().get("actionTakenByEmployee");
   workflowData.getMetaDataMap().put("empAction","agree");
 log.info("Emp Action 1:"+action );
   if(action ==null || action == ""){
        return true;
    }else{
   if(action=="Agree"){
return true;
}else{
return false;
}
}
}

