   var action = workflowData.getMetaDataMap().get("actionTakenByEmployee");
workflowData.getMetaDataMap().put("empAction","disagree");
workflowData.getMetaDataMap().put("empActionFlag","disagree");
  
 log.info("Emp Action 2:"+action );
   if(action ==null || action == ""){
        return false;
    }else{
   if(action=="Disagree"){
return true;
}else{
return false;
}
}
}

